const LINE = 64;
function lineStride(payloadBytes) {
  // we want each counter on its own line; round the payload to a line multiple
  return Math.floor(payloadBytes / LINE) * LINE;
}
function sameLineCount(stride) {
  const offsets = [];
  for (let i = 0; i < 8; i++) offsets.push(i * stride);
  let shared = 0;
  for (let i = 0; i < offsets.length; i++)
    for (let j = i + 1; j < offsets.length; j++)
      if (Math.floor(offsets[i] / LINE) === Math.floor(offsets[j] / LINE)) shared++;
  return shared;
}

tasks.verify:
