// one counter per worker, padded to avoid false sharing
type paddedCounter struct {
	value uint64
	_     [7]uint64 // padding
}

var counters [16]paddedCounter

// hot path: each worker bumps its own counter
func bump(workerId int) {
	counters[workerId].value++
}

// readout: sum all counters
func total() uint64 {
	var sum uint64
	for i := range counters {
		sum += counters[i].value
	}
	return sum
}
